      cwt: 10, cnutrit: 10, msound: MS_SILENT, msize: MZ_TINY, mresists: 0, mconveys: 0,
      mflags1: M1_ANIMAL | M1_NOHANDS | M1_OVIPAROUS | M1_CARNIVORE, mflags2: M2_HOSTILE, mflags3: 0,
